describe('Empty State Illustration for Table', () => {
    beforeEach(() => {
        cy.visit('/table-list'); // Adjust the URL as necessary
    });

    it('should display an empty state illustration when the table has no data', () => {
        // Assuming the table has a data attribute or class to check for empty state
        cy.get('.table').should('not.exist'); // Ensure the table is not present
        cy.get('.empty-state-illustration').should('be.visible'); // Check for empty state illustration
        cy.get('.empty-state-message').should('contain', 'No data available'); // Check for appropriate message
    });

    it('should not display the empty state illustration when the table has data', () => {
        // Simulate adding data to the table
        cy.intercept('GET', '/api/table-data', { fixture: 'tableData.json' }).as('getTableData');
        cy.visit('/table-list');
        cy.wait('@getTableData');

        cy.get('.table').should('be.visible'); // Ensure the table is present
        cy.get('.empty-state-illustration').should('not.exist'); // Ensure empty state illustration is not present
    });
});
